import heapq

def min_days_to_pass_exams(n, m, daily_exams, preparation_time):
    if sum(preparation_time) > n * m:
        return -1

    pq = []
    for i in range(m):
        heapq.heappush(pq, (preparation_time[i], i))

    total_days = 0
    for day in range(n):
        if daily_exams[day] == 0:
            if pq:
                preparation_time, subject = heapq.heappop(pq)
                preparation_time -= 1
                if preparation_time > 0:
                    heapq.heappush(pq, (preparation_time, subject))
                total_days += 1
            else:
                break
        elif preparation_time[daily_exams[day] - 1] > 0:
            preparation_time[daily_exams[day] - 1] -= 1
            total_days += 1
        else:
            heapq.heappush(pq, (-daily_exams[day], daily_exams[day] - 1))
            total_days += 1

    return total_days + len(pq)

